for borough, value in hot_spots:
    if is_surrounded(borough, borough_analysis, is_hot_spot=True):
        validated_hot_spots.append((borough, value))

# Validate cold spots
validated_cold_spots = []
for borough, value in cold_spots:
    if is_surrounded(borough, borough_analysis, is_hot_spot=False):
        validated_cold_spots.append((borough, value))

# Prepare the final output
final_results = []
for borough, value in validated_hot_spots:
    final_results.append(f"{borough} (HH, statistical method={value})")
for borough, value in validated_cold_spots:
